// ==========================================
// PROCEDURE: GLPI_TicketManagement
// ==========================================
// Gerencia chamados/tickets do GLPI

// ==========================================
// MÉTODO: CreateTicket
// ==========================================
// Cria novo chamado no GLPI
Sub 'CreateTicket'
    // Declaração de variáveis
    &HttpClient = new()
    &HTTP_URL = &GLPI_URL + "/Ticket"
    &HTTP_METHOD = "POST"
    &HTTP_STATUS = 0
    &HTTP_RESPONSE = ""
    &TICKET_ID = 0
    &SUCCESS = False
    &ERROR_MESSAGE = ""

    // Configurar headers
    &HttpClient.AddHeader("App-Token", &APP_TOKEN)
    &HttpClient.AddHeader("Session-Token", &SESSION_TOKEN)
    &HttpClient.AddHeader("Content-Type", "application/json")

    // Construir payload JSON com SDT
    &TicketInput = new()
    &TicketInput.name = &TICKET_TITLE
    &TicketInput.content = &TICKET_DESCRIPTION
    &TicketInput.priority = 3 // Média
    &TicketInput.requesttypes_id = 1 // Solicitação
    &TicketInput.type = 1 // Incidente
    &TicketInput.users_id_recipient = &USER_ID
    &TicketInput.entities_id = &ENTITY_ID

    // Wrap input em um objeto "input"
    &Payload = new()
    &Payload.Add( &TicketInput )
    &HttpClient.AddString(&Payload.ToJson()) 

    // Executar requisição
    &HttpClient.Execute(&HTTP_METHOD, &HTTP_URL)

    // Obter status e resposta
    &HTTP_STATUS = &HttpClient.StatusCode
    &HTTP_RESPONSE = &HttpClient.ToString()

    If &HTTP_STATUS = 201 // Created
        &TicketResponse = new()
        &TicketResponse.FromJson(&HTTP_RESPONSE)

        If &TicketResponse.id > 0
            &TICKET_ID = &TicketResponse.id
            &SUCCESS = True
            &ERROR_MESSAGE = ""
        Else
            &SUCCESS = False
            &ERROR_MESSAGE = "Erro ao processar resposta da API"
        EndIf
    Else
        &SUCCESS = False
        &ERROR_MESSAGE = "Erro HTTP: " + &HTTP_STATUS.ToString() + " - " + &HTTP_RESPONSE
    EndIf
EndSub

// Regra de parâmetros
// parm(in:&GLPI_URL, in:&SESSION_TOKEN, in:&APP_TOKEN, in:&TICKET_TITLE, in:&TICKET_DESCRIPTION, in:&USER_ID, in:&ENTITY_ID, out:&TICKET_ID, out:&SUCCESS, out:&ERROR_MESSAGE);

// ==========================================
// MÉTODO: SearchTicketsByStatus
// ==========================================
// Consulta chamados por status vinculados ao usuário
Sub 'SearchTicketsByStatus'
    // Declaração de variáveis
    &HttpClient = new()
    &SEARCH_URL = &GLPI_URL + "/search/Ticket?criteria[0][field]=12&criteria[0][searchtype]=equals&criteria[0][value]=" + &USER_ID.ToString() + "&criteria[1][link]=AND&criteria[1][field]=3&criteria[1][searchtype]=equals&criteria[1][value]=" + &STATUS_ID.ToString()
    &HTTP_METHOD = "GET"
    &HTTP_STATUS = 0
    &HTTP_RESPONSE = ""
    &TICKETS_COLLECTION = new()
    &SUCCESS = False
    &ERROR_MESSAGE = ""

    // Configurar headers
    &HttpClient.AddHeader("App-Token", &APP_TOKEN)
    &HttpClient.AddHeader("Session-Token", &SESSION_TOKEN)

    // Executar requisição
    &HttpClient.Execute(&HTTP_METHOD, &SEARCH_URL)

    // Obter status e resposta
    &HTTP_STATUS = &HttpClient.StatusCode
    &HTTP_RESPONSE = &HttpClient.ToString()

    If &HTTP_STATUS = 200
        &TICKETS_COLLECTION.FromJson(&HTTP_RESPONSE)

        If &TICKETS_COLLECTION.Count > 0
            &SUCCESS = True
            &ERROR_MESSAGE = ""
        Else
            &SUCCESS = False
            &ERROR_MESSAGE = "Nenhum ticket encontrado ou erro ao processar resposta"
        EndIf
    Else
        &SUCCESS = False
        &ERROR_MESSAGE = "Erro HTTP: " + &HTTP_STATUS.ToString()
    EndIf
EndSub

// Regra de parâmetros
// parm(in:&GLPI_URL, in:&SESSION_TOKEN, in:&APP_TOKEN, in:&USER_ID, in:&STATUS_ID, out:&TICKETS_COLLECTION, out:&SUCCESS, out:&ERROR_MESSAGE);

// ==========================================
// MÉTODO: GetTicketDetails
// ==========================================
// Obtém detalhes de um chamado específico
Sub 'GetTicketDetails'
    // Declaração de variáveis
    &HttpClient = new()
    &HTTP_URL = &GLPI_URL + "/Ticket/" + &TICKET_ID.ToString()
    &HTTP_METHOD = "GET"
    &HTTP_STATUS = 0
    &HTTP_RESPONSE = ""
    &TICKET_DETAILS = new()
    &SUCCESS = False

    // Configurar headers
    &HttpClient.AddHeader("App-Token", &APP_TOKEN)
    &HttpClient.AddHeader("Session-Token", &SESSION_TOKEN)

    // Executar requisição
    &HttpClient.Execute(&HTTP_METHOD, &HTTP_URL)

    // Obter status e resposta
    &HTTP_STATUS = &HttpClient.StatusCode
    &HTTP_RESPONSE = &HttpClient.ToString()

    If &HTTP_STATUS = 200
        &TICKET_DETAILS.FromJson(&HTTP_RESPONSE)

        If &TICKET_DETAILS.id > 0
            &SUCCESS = True
        Else
            &SUCCESS = False
        EndIf
    Else
        &SUCCESS = False
    EndIf
EndSub

// Regra de parâmetros
// parm(in:&GLPI_URL, in:&SESSION_TOKEN, in:&APP_TOKEN, in:&TICKET_ID, out:&TICKET_DETAILS, out:&SUCCESS);

// ==========================================
// MÉTODO: UpdateTicketStatus
// ==========================================
// Atualiza status de um chamado
Sub 'UpdateTicketStatus'
    // Declaração de variáveis
    &HttpClient = new()
    &HTTP_URL = &GLPI_URL + "/Ticket/" + &TICKET_ID.ToString()
    &HTTP_METHOD = "PUT"
    &HTTP_STATUS = 0
    &HTTP_RESPONSE = ""
    &SUCCESS = False
    &ERROR_MESSAGE = ""

    // Configurar headers
    &HttpClient.AddHeader("App-Token", &APP_TOKEN)
    &HttpClient.AddHeader("Session-Token", &SESSION_TOKEN)
    &HttpClient.AddHeader("Content-Type", "application/json")

    // Construir payload JSON com SDT
    &TicketInput = new SDT_TicketInput()
    &TicketInput.status = &NEW_STATUS
    &Payload = new()
    &Payload.Add( &TicketInput )
    &HttpClient.AddString( &Payload.ToJson() )

    // Executar requisição
    &HttpClient.Execute(&HTTP_METHOD, &HTTP_URL)

    // Obter status e resposta
    &HTTP_STATUS = &HttpClient.StatusCode
    &HTTP_RESPONSE = &HttpClient.ToString()

    If &HTTP_STATUS = 200
        &SUCCESS = True
        &ERROR_MESSAGE = ""
    Else
        &SUCCESS = False
        &ERROR_MESSAGE = "Erro HTTP: " + &HTTP_STATUS.ToString() + " - " + &HTTP_RESPONSE
    EndIf
EndSub

// Regra de parâmetros
// parm(in:&GLPI_URL, in:&SESSION_TOKEN, in:&APP_TOKEN, in:&TICKET_ID, in:&NEW_STATUS, out:&SUCCESS, out:&ERROR_MESSAGE);
